mapper.select:
SELECT DATE_FORMAT(d.submitted_at, '%Y-%m') AS month,
       COUNT(*) AS count,
       COALESCE(SUM(d.declared_amount), 0) AS amount
FROM tax_declaration d
WHERE d.deleted = 0
  AND d.submitted_at IS NOT NULL
  AND d.submitted_at >= #{start}
  AND d.submitted_at <= #{end}

    AND d.created_by = #{scopeUserId}


    AND d.declaration_type_id = #{typeId}

GROUP BY DATE_FORMAT(d.submitted_at, '%Y-%m')
ORDER BY month
